args.command:
cd /workspace && cat > next.config.ts <<'EOF'
import type { NextConfig } from 'next'

const nextConfig: NextConfig = {
  cacheComponents: true,
  partialPrefetching: true,
}

export default nextConfig
EOF
cat > app/product/page.tsx <<'EOF'
import { Suspense } from 'react'
import { prefetch } from 'next/cache'
import { getRelatedProducts } from '@/lib/data'

export default function ProductPage() {
  return (
    <main>
      <h1>Premium Widget</h1>
      <p>A durable widget for everyday projects.</p>
      <section>
        <h2>Related products</h2>
        <Suspense fallback={<p>Loading related products...</p>}>
          <RelatedProducts />
        </Suspense>
      </section>
    </main>
  )
}

async function RelatedProducts() {
  // Keep related products out of the shared App Shell; they resolve on a
  // per-link prefetch (<Link prefetch={true}>) or on navigation.
  await prefetch()
  const relatedProducts = await getRelatedProducts()

  return (
    <ul>
      {relatedProducts.map((product) => (
        <li key={product}>{product}</li>
      ))}
    </ul>
  )
}
EOF
cat > app/page.tsx <<'EOF'
import Link from 'next/link'

export default function Home() {
  return (
    <main>
      <h1>Featured product</h1>
      <Link href="/product" prefetch={true}>
        View Premium Widget
      </Link>
    </main>
  )
}
EOF
npx next build 2>&1 | tail -30

